  "set.credsCleared": { en: "CHIP credentials cleared.", ms: "Kredensial CHIP dikosongkan.", zh: "已清除 CHIP 凭证。", ta: "CHIP சான்றுகள் அழிக்கப்பட்டன.", ar: "تم مسح بيانات CHIP." },
  "set.domainsTitle": { en: "Custom domains", ms: "Domain tersuai", zh: "自定义域名", ta: "தனிப்பயன் டொமைன்கள்", ar: "النطاقات المخصصة" },
  "set.domainsHelp": { en: "Serve your forms on your own domains — as many as you like. For each: add a CNAME your-domain → jomform.com (DNS only), then Verify. Once verified, routing + the TLS certificate are provisioned automatically — no Cloudflare account or auto-setup needed.", ms: "Serve borang di domain anda sendiri — sebanyak mana pun. Untuk setiap satu: tambah CNAME domain-anda → jomform.com (DNS sahaja), kemudian Verify. Selepas disahkan, routing + sijil TLS disediakan automatik — tanpa akaun Cloudflare atau auto-setup.", zh: "在您自己的域名上托管表单 — 数量不限。每个域名：添加 CNAME（仅 DNS）指向 jomform.com，然后验证。验证后，路由和 TLS 证书自动配置 — 无需 Cloudflare 账户。", ta: "உங்கள் சொந்த டொமைன்களில் படிவங்களை இயக்கவும் — எத்தனை வேண்டுமானாலும். ஒவ்வொன்றிற்கும்: CNAME சேர்த்து (DNS மட்டும்) jomform.com-ஐ சுட்டவும், பின் சரிபார்க்கவும். சரிபார்த்தவுடன் ரூட்டிங் + TLS சான்றிதழ் தானாக ஒதுக்கப்படும்.", ar: "استضف نماذجك على نطاقاتك الخاصة — بلا حدود. لكل نطاق: أضف CNAME (DNS فقط) إلى jomform.com، ثم تحقق. بعد التحقق، يتم توفير التوجيه وشهادة TLS تلقائياً." },
  "set.addDomain": { en: "Add domain", ms: "Tambah domain", zh: "添加域名", ta: "டொமைன் சேர்க்க", ar: "إضافة نطاق" },
  "set.domainAdded": { en: "{domain} added. Add CNAME {domain} → jomform.com, then Verify.", ms: "{domain} ditambah. Tambah CNAME {domain} → jomform.com, kemudian Verify.", zh: "{domain} 已添加。添加 CNAME {domain} → jomform.com，然后验证。", ta: "{domain} சேர்க்கப்பட்டது. CNAME {domain} → jomform.com சேர்த்து, பின் சரிபார்க்கவும்.", ar: "تمت إضافة {domain}. أضف CNAME {domain} → jomform.com، ثم تحقق." },
  "set.failedAddDomain": { en: "Failed to add domain", ms: "Gagal tambah domain", zh: "添加域名失败", ta: "டொமைன் சேர்க்க தோல்வி", ar: "فشل إضافة النطاق" },
  "set.domainVerified": { en: "{domain} verified ✓", ms: "{domain} disahkan ✓", zh: "{domain} 已验证 ✓", ta: "{domain} சரிபார்க்கப்பட்டது ✓", ar: "{domain} تم التحقق ✓" },
  "set.verifyFailed": { en: "{domain}: verify failed", ms: "{domain}: pengesahan gagal", zh: "{domain}：验证失败", ta: "{domain}: சரிபார்ப்பு தோல்வி", ar: "{domain}: فشل التحقق" },
  "set.verified": { en: "verified ✓", ms: "disahkan ✓", zh: "已验证 ✓", ta: "சரிபார்க்கப்பட்டது ✓", ar: "تم التحقق ✓" },
  "set.pendingDns": { en: "pending DNS — CNAME to jomform.com, then Verify", ms: "menunggu DNS — CNAME ke jomform.com, kemudian Verify", zh: "等待 DNS — CNAME 到 jomform.com，然后验证", ta: "DNS நிலுவையில் — jomform.com-க்கு CNAME, பின் சரிபார்க்கவும்", ar: "بانتظار DNS — CNAME إلى jomform.com ثم تحقق" },
